/* ===== Monthly record ===== */
function rpProgress(rows){
  const names=[...new Set(rows.map(r=>r.name))].sort();
  return names.map(nm=>{
    const rs=rows.filter(r=>r.name===nm), mins=rs.reduce((a,r)=>a+(+r.dur||0),0), out=[];
    out.push(['Lessons',rs.length+(rs.length>1?' lessons':' lesson')+(mins?' · '+rpDur(mins):'')]);
    const nw=rpSurahRanges(rs,'quran.new'), rv=rpSurahRanges(rs,'quran.rev');
    if(nw.length) out.push(['Qur’an – New memorisation',nw.join('; ')]);
    if(rv.length) out.push(['Qur’an – Revision',rv.join('; ')]);
    const uniq=k=>[...new Set(rs.map(r=>((r.data||{})[k]||'').toString().trim()).filter(Boolean))];
    const ar=uniq('arabic.done'); if(ar.length) out.push(['Arabic Language',ar.join('\n')]);
    const pg=[]; rs.forEach(r=>{ const d=r.data||{}; [d['noor.page'],d['noor.page2']].forEach(v=>{ if(+v) pg.push(+v); }); });
    if(pg.length){ const a=Math.min(...pg), b=Math.max(...pg); out.push(['Noor El-Bayan',a===b?'Page '+a:'Pages '+a+'–'+b]); }
    const tj=uniq('tajweed.done'); if(tj.length) out.push(['Tajweed',tj.join('\n')]);
    const is=uniq('islamic.done'); if(is.length) out.push(['Islamic Studies',is.join('\n')]);
    const g={}; rs.forEach(r=>{ const k=(r.grade||'').split(/[,!\s]/)[0]; if(k) g[k]=(g[k]||0)+1; });
    const gs=Object.keys(g).map(k=>k+' ×'+g[k]).join(', '); if(gs) out.push(['Grades',gs]);
    return {name:nm,rows:out};
  });
}
function rpSurahRanges(rows,key){
  const by={}; rows.forEach(r=>{ const a=(r.data||{})[key]; if(!Array.isArray(a)) return; a.forEach(e=>{ const sr=RP_SURAHS[(+e.s)-1]; if(!sr) return; const n=sr[1], f=Math.max(1,Math.min(+e.f||1,n)), t=Math.max(f,Math.min(+e.t||n,n)); const b=by[e.s]=by[e.s]||{f,t}; b.f=Math.min(b.f,f); b.t=Math.max(b.t,t); }); });
  return Object.keys(by).sort((a,b)=>a-b).map(k=>{ const sr=RP_SURAHS[k-1], b=by[k]; return 'Surah '+sr[0]+(b.f===1&&b.t===sr[1]?' (full surah)':b.f===b.t?' (verse '+b.f+')':' (verses '+b.f+'–'+b.t+')'); });
}
function rpMonthModel(){
  const ym=$('rpMonth').value||'', scope=($('rpScope')&&$('rpScope').value)||'', rows=rpAll().filter(r=>(r.date||'').startsWith(ym)&&(!scope||r.name===scope)).sort((a,b)=>(a.date||'').localeCompare(b.date||'')||(a.saved||0)-(b.saved||0));
  const keys=allSubKeys(rows).filter(k=>rows.some(r=>(r.subjects||[]).includes(k))), labs=keys.map(k=>rpSub(k).label);
  const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  let total=0; const by={};
  const list=rows.map((r,i)=>{ const m=+r.dur||0; total+=m; const b=by[r.name]=by[r.name]||{n:0,m:0}; b.n++; b.m+=m;
    const d=/^(\d{4})-(\d\d)-(\d\d)$/.exec(r.date||''); const day=d?days[new Date(+d[1],+d[2]-1,+d[3]).getDay()]:'';
    return {no:i+1,name:r.name,day,date:rpDMY(r.date),dur:rpDur(m)||'—',note:{late:'Late',short:'Shortened',extra:'Extended'}[r.timing]||''}; });
  let title=ym; const mm=/^(\d{4})-(\d\d)$/.exec(ym); if(mm) title=new Date(+mm[1],+mm[2]-1,1).toLocaleString('en-US',{month:'long',year:'numeric'});
  return {note:(scope&&$('rpMNote'))?$('rpMNote').value.trim():'',scope,prog:($('rpProg')&&$('rpProg').checked)?rpProgress(rows):null,acRaw:$('rpAcademy').value.trim(),subRaw:$('rpAcSub').value.trim(),ac:($('rpAcademy').value.trim()||'Academy Name'),sub:$('rpAcSub').value.trim(),teacher:$('rpTeacher').value.trim(),
    subj:labs.length>1?labs.slice(0,-1).join(', ')+' & '+labs[labs.length-1]:(labs[0]||'—'),month:title,list,total,by};
}
function rpMonthHTML(m){
  const e=rpEsc, n=m.list.length, tot=m.total.toLocaleString('en-US'), k=(a,b)=>'<td class="k">'+a+'</td><td dir="auto">'+e(b)+'</td>';
  let h='<div class="mw lay-'+(rpTh('m').lay||'classic')+(rpTh('m').plain?'':' t')+'">'+(MR_LOGO?'<div class="mw-logo"><img src="'+MR_LOGO+'" alt=""></div>':'')+'<div class="mw-ac" dir="auto">'+e(m.ac.toUpperCase())+'</div><div class="mw-t">Teacher Lesson Record – '+e(m.month)+'</div>';
  h+='<table class="mw-a"><tr>'+k('Teacher Name',m.teacher||'—')+k('Subject',m.subj)+'</tr><tr>'+k('Month',m.month)+k('Total Lessons',n)+'</tr></table>';
  h+='<table class="mw-l"><colgroup><col style="width:6.7%"><col style="width:27.4%"><col style="width:12.6%"><col style="width:13.3%"><col style="width:17%"><col style="width:23%"></colgroup><tr><th>No.</th><th>Student Name</th><th>Day</th><th>Date</th><th>Lesson Duration</th><th>Notes</th></tr>'
    +m.list.map(x=>'<tr><td>'+x.no+'</td><td dir="auto">'+e(x.name)+'</td><td>'+x.day+'</td><td>'+x.date+'</td><td>'+x.dur+'</td><td dir="auto">'+e(x.note)+'</td></tr>').join('')+'</table>';
  h+='<table class="mw-a"><tr>'+k('Total Lessons',n)+k('Total Minutes',tot)+'</tr><tr>'+k('Total Hours',rpDur(m.total)||'0')+k('Teacher Signature','')+'</tr></table>';
  if(m.prog&&m.prog.length) h+='<div class="mw-ps">Progress Summary</div>'+m.prog.map(b=>'<table class="mw-a"><tr><td class="k" colspan="2">'+e(b.name)+'</td></tr>'+b.rows.map(r=>'<tr>'+k(r[0],r[1])+'</tr>').join('')+'</table><div style="height:6px"></div>').join('');
  if(m.note) h+='<div class="mw-ps">'+(m.scope?e(m.scope)+' \u2014 ':'')+'Teacher\u2019s Assessment</div><div class="mw-note" dir="auto">'+e(m.note)+'</div>';
  return h+'<div class="mw-f" dir="auto">'+e(m.ac)+(m.sub?' – '+e(m.sub):'')+'</div></div>';
}
function rpMonthRender(){ const sc=$('rpScope'); if(sc){ const v=sc.value, names=[...new Set(rpAll().map(r=>r.name).filter(Boolean))].sort(); sc.innerHTML='<option value="">All students</option>'+names.map(n=>'<option>'+rpEsc(n)+'</option>').join(''); sc.value=names.includes(v)?v:''; }
  if($('rpMAI')) $('rpMAI').title=sc&&sc.value?'':'Choose one student first';
  if($('rpMonthView')) $('rpMonthView').innerHTML=rpMonthHTML(rpMonthModel()); }

let RP_MAI_OLD='';
async function rpMonthAI(btn){
  const sc=$('rpScope').value; if(!sc){ toast(RPL==='ar'?'\u0627\u062e\u062a\u0631 \u0637\u0627\u0644\u0628\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0623\u0648\u0644\u0627\u064b':'Choose one student first'); return; }
  if(!S.ai.key){ toast(RPL==='ar'?'\u0623\u0636\u0641 \u0645\u0641\u062a\u0627\u062d API \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a (Setup)':'Add your API key in Setup first'); return; }
  const ym=$('rpMonth').value||'', rows=rpAll().filter(r=>(r.date||'').startsWith(ym)&&r.name===sc).sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  if(!rows.length){ toast('No saved reports for this student in this month'); return; }
  const pr=rpProgress(rows)[0], facts=pr.rows.map(r=>r[0]+': '+r[1]).join('\n');
  const per=rows.map(r=>{ const m=rpModel(r); return rpDMY(r.date)+' \u2014 '+m.notes.map(n=>n.rows.map(x=>x[1]).join(' ')).join(' | ')+(m.hw.length?' (homework: '+m.hw.map(x=>x.text).join('; ')+')':''); }).join('\n').slice(0,2500);
  const cur=$('rpMNote').value.trim(), lang=(RPL==='ar'||/[\u0600-\u06FF]/.test(cur))?'Arabic':'English';
  const old=btn.textContent; btn.disabled=true; btn.textContent='\u2026';
  try{
    let out=await callAI('You are a caring Islamic studies teacher writing the monthly assessment of ONE student for the parent.\nStudent: '+sc+'\nMonth: '+ym+'\n\nSummary facts:\n'+facts+'\n\nLesson-by-lesson notes:\n'+per+(cur?'\n\nTeacher\u2019s own draft to improve (keep its meaning and facts):\n'+cur:'')+'\n\nWrite 3\u20135 warm, professional sentences: what the student achieved this month, strengths, one or two areas to work on, and a short encouraging recommendation. Use ONLY the facts above \u2014 invent nothing (no surahs, pages, numbers, grades or behaviour that is not listed). Do not assume the student\u2019s gender if it is not clear. Write in '+lang+'. Output ONLY the text, no title, no quotes, no markdown.');
    out=String(out||'').trim().replace(/^["\u201c\u00ab]+|["\u201d\u00bb]+$/g,'').trim(); if(!out) throw new Error('Empty result');
    RP_MAI_OLD=$('rpMNote').value; $('rpMNote').value=out; $('rpMAIUndo').hidden=!RP_MAI_OLD; rpMonthRender(); toast('Assessment written \u2713');
  }catch(e){ toast(String(e.message||e).slice(0,90)); }
  btn.disabled=false; btn.textContent=old;
}
function rpMonthText(){
  const m=rpMonthModel(), L=[m.ac.toUpperCase(),'Teacher Lesson Record – '+m.month,'Teacher: '+(m.teacher||'—')+' | Subject: '+m.subj,'','No.\tStudent\tDay\tDate\tDuration\tNotes'];
  m.list.forEach(x=>L.push([x.no,x.name,x.day,x.date,x.dur,x.note].join('\t')));
  L.push('','Total Lessons: '+m.list.length,'Total Minutes: '+m.total.toLocaleString('en-US'),'Total Hours: '+(rpDur(m.total)||'0'));
  if(m.note) L.push('','Teacher\u2019s Assessment'+(m.scope?' \u2014 '+m.scope:'')+':',m.note);
  return L.join('\n');
}
function rpMonthPrint(){ rpPrintDoc('Lesson Record',rpMonthHTML(rpMonthModel()),'.mw{max-width:none}'); }
function rpMonthDoc(){
  const m=rpMonthModel(), html='<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><style>'+RP_CSS+MR_CSS+rpThemeCSS()+'</style></head><body>'+rpMonthHTML(m)+'</body></html>';
  const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob(['﻿',html],{type:'application/msword'})); a.download='Lesson_Record_'+m.month.replace(/\s+/g,'_')+'.doc'; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),2000);
}

let MR_LOGO='';
const MR_CSS=`.mw{max-width:760px;margin:0 auto;background:#fff;color:#000;font-family:Cambria,'Times New Roman',Georgia,serif;font-size:11pt;padding:6px 2px;line-height:1.25}.mw-logo{text-align:center}.mw-logo img{width:158px;height:auto}.mw-ac{text-align:center;font-weight:700;font-size:18pt;margin:6px 0}.mw-t{text-align:center;font-weight:700;font-size:14pt;margin:8px 0 14px}.mw table{border-collapse:collapse;width:100%;margin:0 auto 16px;table-layout:fixed}.mw td,.mw th{border:1px solid #000;padding:1px 6px;text-align:start;vertical-align:middle;font-weight:400;background:#fff;color:#000;word-wrap:break-word}.mw .k,.mw th{font-weight:700}.mw .mw-l{width:91%}.mw .mw-l td,.mw .mw-l th{font-size:9pt}.mw-f{text-align:center;font-style:italic;font-size:9pt}`;
async function mrLogoLoad(){
  try{ const buf=mrTpl().bytes, {dv,list}=mrZipList(buf), f=list.find(x=>/^word\/media\/.+\.(jpe?g|png|gif)$/i.test(x.name)); if(!f){ MR_LOGO=''; return; }
    const ds=f.lo+30+dv.getUint16(f.lo+26,true)+dv.getUint16(f.lo+28,true), d=buf.subarray(ds,ds+f.csize);
    const u=f.method===0?d:new Uint8Array(await new Response(new Blob([d]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());
    const ext=f.name.split('.').pop().toLowerCase(); MR_LOGO='data:image/'+(ext==='jpg'?'jpeg':ext)+';base64,'+mrU2B(u); }catch(e){ MR_LOGO=''; }
  try{ rpMonthRender(); }catch(e){}
}
/* ===== Word form (.docx) fill — uses your uploaded form or the built-in one ===== */
const MR_KEY='lp.mr.tpl'; let mrMem=null;
function mrB2U(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u;}
function mrU2B(u){let s='';for(let i=0;i<u.length;i+=32768)s+=String.fromCharCode.apply(null,u.subarray(i,i+32768));return btoa(s);}
