function mrFill(xml,m){
  const W='http://schemas.openxmlformats.org/wordprocessingml/2006/main', doc=new DOMParser().parseFromString(xml,'application/xml');
  if(doc.getElementsByTagName('parsererror').length) throw new Error('bad xml');
  const g=(el,t)=>Array.from(el.getElementsByTagNameNS(W,t)), tx=el=>g(el,'t').map(t=>t.textContent).join('').trim();
  const setText=(host,text)=>{
    const p=host.localName==='p'?host:g(host,'p')[0]; if(!p) return;
    const runs=Array.from(p.childNodes).filter(n=>n.localName==='r'); let r=runs[0];
    if(!r){ r=doc.createElementNS(W,'w:r'); p.appendChild(r); }
    runs.forEach(x=>Array.from(x.childNodes).filter(n=>n.localName==='t').forEach(n=>x.removeChild(n)));
    runs.slice(1).forEach(x=>p.removeChild(x));
    if(text!==''){ const t=doc.createElementNS(W,'w:t'); t.setAttributeNS('http://www.w3.org/XML/1998/namespace','xml:space','preserve'); t.textContent=String(text); r.appendChild(t);
      if(/[\u0600-\u06FF]/.test(text)){ const mk=n=>doc.createElementNS(W,'w:'+n); let pr=Array.from(r.childNodes).find(n=>n.localName==='rPr'); if(!pr){ pr=mk('rPr'); r.insertBefore(pr,r.firstChild); }
        const has=n=>Array.from(pr.childNodes).find(x=>x.localName===n), sz=has('sz'), b=has('b');
        if(sz&&!has('szCs')){ const c=mk('szCs'); c.setAttributeNS(W,'w:val',sz.getAttributeNS(W,'val')); sz.after(c); }
        if(b&&!has('bCs')) b.after(mk('bCs'));
        if(!/[A-Za-z]/.test(text)&&!has('rtl')) pr.appendChild(mk('rtl')); } }
  };
  let lt=null;
  for(const t of g(doc,'tbl')){ const r0=g(t,'tr')[0]; if(!r0) continue; const h=g(r0,'tc').map(c=>tx(c).toLowerCase()); if(h.some(x=>/^(no\.?|#|م|رقم)$/.test(x))&&h.some(x=>/student|name|الطالب/.test(x))){ lt=t; break; } }
  if(!lt) throw new Error('no lessons table');
  for(const p of g(doc,'p')){ if(p.parentNode.localName!=='body') continue; const s=tx(p); if(/Lesson Record\s*[–-]/i.test(s)) setText(p,s.replace(/(Lesson Record\s*[–-]\s*).*/i,'$1'+m.month)); }
  { const bp=g(doc,'p').filter(p=>p.parentNode.localName==='body'), ti=bp.findIndex(p=>/Lesson Record\s*[–-]/i.test(tx(p)));
    if(m.acRaw){ const a=ti>0?bp[ti-1]:null; if(a&&tx(a)&&!g(a,'drawing').length) setText(a,m.acRaw.toUpperCase()); const f=bp[bp.length-1]; if(f&&bp.length-1>ti&&tx(f)) setText(f,m.acRaw+(m.subRaw?' – '+m.subRaw:'')); } }
  const n=m.list.length, vals={'اسم المعلم':m.teacher,'الشهر':m.month,'عدد الدروس':n,'إجمالي الدروس':n,'إجمالي الدقائق':m.total.toLocaleString('en-US'),'إجمالي الساعات':rpDur(m.total)||'0','teacher name':m.teacher,'month':m.month,'total lessons':n,'total minutes':m.total.toLocaleString('en-US'),'total hours':rpDur(m.total)||'0'};
  for(const t of g(doc,'tbl')){ if(t===lt) continue; for(const tc of g(t,'tc')){ const k=tx(tc).toLowerCase().replace(/:$/,''), nx=tc.nextElementSibling;
    if(nx&&nx.localName==='tc'&&k in vals&&vals[k]!==''&&vals[k]!=null) setText(nx,vals[k]);
    else if(nx&&nx.localName==='tc'&&(k==='subject'||k==='المادة')&&!tx(nx)&&m.subj&&m.subj!=='—') setText(nx,m.subj); } }
  const rows=g(lt,'tr'), hdr=g(rows[0],'tc').map(c=>{const s=tx(c).toLowerCase(); return /^(note|ملاحظ)/.test(s)?'note':/^(م|رقم)$/.test(s)?'no':/اسم الطالب|^الطالب/.test(s)?'name':/^اليوم/.test(s)?'day':/^التاريخ/.test(s)?'date':/مدة/.test(s)?'dur':/^(no\.?|#|number)$/.test(s)?'no':/student|name/.test(s)?'name':/day/.test(s)?'day':/date/.test(s)?'date':/dur|time/.test(s)?'dur':'';});
  const proto=rows[1]; if(!proto) throw new Error('no sample row');
  rows.slice(1).forEach(r=>r.parentNode.removeChild(r));
  for(const it of m.list){ const r=proto.cloneNode(true); g(r,'tc').forEach((c,i)=>{ if(hdr[i]) setText(c,it[hdr[i]]==null?'':it[hdr[i]]); }); lt.appendChild(r); }
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'+new XMLSerializer().serializeToString(doc).replace(/^<\?xml[^>]*\?>\s*/,'');
}
async function mrBuild(m,tpl){
  const xml=await mrRead(tpl,'word/document.xml'); if(!xml) throw new Error('no document.xml');
  return mrReplace(tpl,'word/document.xml',new TextEncoder().encode(mrFill(xml,m)));
}
async function mrDocx(){
  try{
    const m=rpMonthModel(); if(!m.list.length){ toast('No lessons saved for this month'); return; }
    const blob=await mrBuild(m,mrTpl().bytes), a=document.createElement('a');
    a.href=URL.createObjectURL(blob); a.download='Teacher_Lesson_Record_'+m.month.replace(/\s+/g,'_')+'.docx'; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),2000);
  }catch(e){ toast('Could not build Word file — try re-uploading your form'); }
}
async function mrUpload(file){
  try{
    const u=new Uint8Array(await file.arrayBuffer()); await mrBuild({month:'Test',teacher:'',total:0,list:[]},u);
    const o={n:file.name,d:mrU2B(u)}; mrMem=o; try{ localStorage.setItem(MR_KEY,JSON.stringify(o)); }catch(e){ toast('Form loaded for this session only (storage full)'); mrStatus(); return; }
    mrStatus(); mrLogoLoad(); toast('Form saved ✅ — Word export will use it');
  }catch(e){ toast('Form needs a lessons table with “No.” and “Student” headers'); }
}

const MR_DEFAULT_TPL="";
function rpInit(){
  if(!REPF.ready){
    REPF.ready=true;
    const st=document.createElement('style'); st.textContent=RP_CSS+MR_CSS; document.head.appendChild(st);
    try{ $('rpStyle').value=lsGet('lp.rep.style')||'exec'; }catch(e){}
    try{ const sv=JSON.parse(lsGet('lp.rep.prefs')||'null'); if(sv){ if(Array.isArray(sv.subjects)&&sv.subjects.length) REPF.subjects=sv.subjects.filter(k=>rpSub(k)); $('rpTeacher').value=sv.teacher||''; $('rpBis').checked=sv.bis!==false; $('rpShowAc').checked=sv.showAc!==false; } }catch(e){}
    $('rpDate').value=rpToday(); $('rpMonth').value=rpToday().slice(0,7);
    try{ const ac=JSON.parse(lsGet('lp.rep.acad')||'null'); if(ac){ $('rpAcademy').value=ac.a||''; $('rpAcSub').value=ac.s||''; } else { $('rpAcademy').value=''; $('rpAcSub').value=''; } }catch(e){}
    rpChips(); rpBuildSections(); clInit(); mrStatus(); rpDesignInit(); rpApplyDesign(); rpSetLang(RPL); rpTab(lsGet('lp.rep.tab')||'write'); mrLogoLoad();
    const view=$('view-reports');
    view.addEventListener('input',e=>{ const t=e.target; if(t.id==='rpH'||t.id==='rpM') t.value=t.value.replace(/[٠-٩]/g,c=>c.charCodeAt(0)-1632).replace(/[۰-۹]/g,c=>c.charCodeAt(0)-1776).replace(/\D/g,'').slice(0,t.id==='rpH'?2:3); },true);
    view.addEventListener('keydown',e=>{ if(e.key==='Enter'&&(e.target.id==='rpNewGrade'||e.target.id==='rpTName')){ e.preventDefault(); (e.target.id==='rpNewGrade'?$('rpAddGrade'):$('rpTSave')).click(); } });
    view.addEventListener('click',e=>{
      const dg=e.target.closest('[data-delgrade]'); if(dg){ e.stopImmediatePropagation(); const g=dg.dataset.delgrade; lsSet('lp.rep.cg',JSON.stringify(rpCG().filter(x=>x!==g))); rpChips(); return; }
      const b=e.target.closest('button'); if(!b) return;
      if(b.dataset.tab){ rpTab(b.dataset.tab); return; }
      if(b.dataset.th){ rpPick(b.dataset.th); return; }
      if(b.dataset.ap){ RP_AP=b.dataset.ap; document.querySelectorAll('#rpApply [data-ap]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.ap===RP_AP))); return; }
      if(b.id==='rpAddGrade'){ const g=$('rpNewGrade').value.trim(); if(!g) return; const L=rpCG(); if(!L.includes(g)&&!RP_GRADES.includes(g)){ L.push(g); lsSet('lp.rep.cg',JSON.stringify(L)); } REPF.grade=g; $('rpNewGrade').value=''; rpChips(); rpPreview(); }
      else if(b.id==='rpTSave') rpTSave(); else if(b.id==='rpTDel') rpTDel();
    });
    view.addEventListener('input',e=>{
      const t=e.target, k=t.dataset&&t.dataset.k, qf=t.dataset&&t.dataset.qf;
      if(t.dataset&&t.dataset.qs!==undefined){ const sel=t.nextElementSibling&&t.nextElementSibling.querySelector('select[data-qf="s"]'); if(sel){ const cur=sel.value; sel.innerHTML=rpOpts(t.value,cur); const os=[...sel.options].filter(o=>o.value);
          if(t.value.trim()){ sel.size=Math.min(os.length+1,7); if(os.length===1){ sel.value=os[0].value; sel.dispatchEvent(new Event('input',{bubbles:true})); } else if(cur&&os.some(o=>o.value===cur)) sel.value=cur; } else sel.removeAttribute('size'); } return; }
      if(k){ if(k[0]==='d') REPF.data[k.slice(2)]=t.value; else REPF.hw[k.slice(2)]=t.value; }
      if(qf){ const en=rpQRef(t.dataset.q)[+t.dataset.i]; if(en){ en[qf]=t.value;
        if(qf==='s'){ const n=RP_SURAHS[(+t.value)-1]; en.f=n?'1':''; en.t=n?String(n[1]):''; const row=t.parentNode; row.querySelector('[data-qf="f"]').value=en.f; row.querySelector('[data-qf="t"]').value=en.t;
          if(t.tagName==='SELECT'){ t.removeAttribute('size'); t.innerHTML=rpOpts('',en.s); t.value=en.s; const si=row.previousElementSibling; if(si&&si.dataset&&si.dataset.qs!==undefined) si.value=''; if(t.blur) t.blur(); } } } }
      if(t.id==='rpName') rpHint();
      if(t.id==='rpSearch') return rpList();
      if(['rpTeacher','rpMonth','rpAcademy','rpAcSub','rpScope','rpProg','rpMNote'].includes(t.id)){ if(t.id==='rpAcademy'||t.id==='rpAcSub') lsSet('lp.rep.acad',JSON.stringify({a:$('rpAcademy').value,s:$('rpAcSub').value})); rpMonthSoon(); if(t.id!=='rpTeacher'&&t.id!=='rpAcademy') return; }
      rpPreviewSoon();
    });
    view.addEventListener('keydown',e=>{ const t=e.target; if(e.key==='Enter'&&t.dataset&&t.dataset.addst!==undefined){ e.preventDefault(); const bt=[...view.querySelectorAll('[data-act="addst"]')].find(x=>x.dataset.for===t.dataset.addst); if(bt) bt.click(); } });
    view.addEventListener('change',e=>{ if(['rpShowAc','rpBis'].includes(e.target.id)){ rpPrefs(); rpPreview(); } if(e.target.id==='rpStyle'){ lsSet('lp.rep.style',e.target.value); rpPreview(); } if(rpDesignChange(e.target)) return; if(e.target.id==='rpMTplIn'){ const f=e.target.files[0]; e.target.value=''; if(f) mrUpload(f); return; } if(e.target.id==='rpFilter') rpList(); if(e.target.id==='rpName') rpHint(); });
    view.addEventListener('click',e=>{
      const dst=e.target.closest('[data-delst]'); if(dst){ e.stopPropagation(); const o=rpCst(), k=dst.dataset.delst; o[k]=(o[k]||[]).filter(x=>x!==dst.dataset.t); lsSet('lp.rep.cst',JSON.stringify(o)); rpBuildSections(); return; }
      const ds=e.target.closest('[data-delsub]'); if(ds){ e.stopPropagation(); const k=ds.dataset.delsub; if(confirm('Remove subject “'+k.slice(2)+'”? Old reports keep it.')){ lsSet('lp.rep.cs',JSON.stringify(rpCS().filter(l=>'x_'+l!==k))); const i=REPF.subjects.indexOf(k); if(i>=0) REPF.subjects.splice(i,1); rpPrefs(); rpChips(); rpBuildSections(); rpPreview(); } return; }
      const b=e.target.closest('button'); if(!b) return; const act=b.dataset.act; if(b.dataset.lang){ rpSetLang(b.dataset.lang); return; }
      if(b.dataset.sub){ const k=b.dataset.sub, i=REPF.subjects.indexOf(k); if(i>=0) REPF.subjects.splice(i,1); else REPF.subjects=allSubKeys().filter(x=>REPF.subjects.includes(x)||x===k);
        rpPrefs(); rpChips(); rpBuildSections(); rpPreview(); }
      else if(b.dataset.grade){ REPF.grade=b.dataset.grade; rpChips(); rpPreview(); }
      else if(b.dataset.dm){ rpSetDur(b.dataset.dm); rpPreview(); }
      else if(act==='st'){ const ta=view.querySelector('textarea[data-k="'+b.dataset.for+'"]'); if(!ta) return; const cur=ta.value.replace(/\s+$/,''); ta.value=(cur?cur+'\n':'')+b.dataset.t+' ';
        const k=b.dataset.for; if(k[0]==='d') REPF.data[k.slice(2)]=ta.value; else REPF.hw[k.slice(2)]=ta.value; ta.focus(); ta.setSelectionRange(ta.value.length,ta.value.length); rpPreview(); }
      else if(act==='by'){ const g=n=>(view.querySelector('[data-by="'+n+'"]').value||'').trim(), bk=g('b'), un=g('u'), ls=g('l'); if(!bk||!un||!ls){ toast('Enter book, unit and lesson'); return; }
        const ta=view.querySelector('textarea[data-k="d:arabic.done"]'), t='We continued our study using the Arabic Bayna Yadayk curriculum (Book '+bk+', Unit '+un+', Lesson '+ls+').';
        ta.value=(ta.value.trim()?ta.value.trim()+'\n':'')+t; REPF.data['arabic.done']=ta.value; lsSet('lp.rep.by',JSON.stringify({b:bk,u:un,l:ls})); rpPreview(); toast('Added \u2713'); }
      else if(act==='tp'){ const a=REPF.data['noor.topics']=REPF.data['noor.topics']||[], i=a.indexOf(b.dataset.t); if(i>=0) a.splice(i,1); else a.push(b.dataset.t); b.setAttribute('aria-pressed',String(i<0)); rpPreview(); }
      else if(act==='polish'||act==='polundo') rpPolish(b,act);
      else if(act==='addst'){ const k=b.dataset.for, inp=[...view.querySelectorAll('[data-addst]')].find(x=>x.dataset.addst===k), t=inp?inp.value.replace(/["'<>&]/g,'').trim():''; if(!t) return; const o=rpCst(); o[k]=o[k]||[]; if(!o[k].includes(t)) o[k].push(t); lsSet('lp.rep.cst',JSON.stringify(o)); rpBuildSections(); }
      else if(act==='addq'){ rpQRef(b.dataset.q).push({s:'',f:'',t:''}); rpBuildSections(); }
      else if(act==='delq'){ rpQRef(b.dataset.q).splice(+b.dataset.i,1); rpBuildSections(); rpPreview(); }
      else if(act==='lastq'){ const nm=$('rpName').value.trim().toLowerCase(); if(!nm){ toast('Enter the student’s name first'); $('rpName').focus(); return; }
        const last=rpAll().filter(r=>(r.name||'').toLowerCase()===nm&&r.id!==REPF.id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.saved||0)-(a.saved||0))[0], hw=last&&last.hw&&last.hw.quran;
        if(!Array.isArray(hw)||!hw.some(x=>x&&x.s)){ toast('No Qur’an homework found in this student’s last report'); return; }
        const cur=rpQRef('rev').filter(x=>x.s), add=hw.filter(x=>x&&x.s&&!cur.some(c=>c.s==x.s&&c.f==x.f&&c.t==x.t));
        REPF.data['quran.rev']=cur.concat(JSON.parse(JSON.stringify(add))); rpBuildSections(); rpPreview(); toast('Last homework added to Revision ✓'); }
      else if(act==='sameq'){ REPF.hw.quran=JSON.parse(JSON.stringify(rpQRef('new'))); rpBuildSections(); rpPreview(); }
      else if(b.id==='rpSave'){ const r=rpCur(); if(!r.name){ toast('Enter the student’s name'); $('rpName').focus(); return; }
        const a=rpAll(); r.id=r.id||'r'+Date.now().toString(36); r.saved=Date.now(); REPF.id=r.id;
        const i=a.findIndex(x=>x.id===r.id); if(i>=0) a[i]=r; else a.push(r); rpStore(a); rpPrefs(); toast('Report saved ✅'); rpList(); clSyncNow(true); rpReset(); }
      else if(b.id==='rpCopy') rpCopyText(rpText(rpModel(rpCur())));
      else if(b.id==='rpWa') window.open('https://wa.me/?text='+encodeURIComponent(rpText(rpModel(rpCur()))),'_blank');
      else if(b.id==='rpWaImg'){ const m=rpModel(rpCur()); rpToPng(rpHTML(m),600,'Lesson_Report_'+($('rpName').value.trim()||'student')+'_'+$('rpDate').value,rpText(m)); }
      else if(b.id==='rpWaPdf'){ const m=rpModel(rpCur()); window.RP_PDF=true; Promise.resolve(rpToPng(rpHTML(m),600,'Lesson_Report_'+($('rpName').value.trim()||'student')+'_'+$('rpDate').value,rpText(m))).finally(()=>{window.RP_PDF=false;}); }
      else if(b.id==='rpPrint') rpPrint();
      else if(b.id==='rpMPrint') rpMonthPrint();
      else if(b.id==='rpMDoc') mrDocx();
      else if(b.id==='rpAddSub'){ const l=$('rpNewSub').value.replace(/["'<>&]/g,'').trim(); if(!l) return; const L=rpCS(); if(!L.includes(l)&&!Object.values(RP_SUBJECTS).some(x=>x.label.toLowerCase()===l.toLowerCase())){ L.push(l); lsSet('lp.rep.cs',JSON.stringify(L)); } if(!REPF.subjects.includes('x_'+l)&&!RP_SUBJECTS[l]) REPF.subjects.push('x_'+l); $('rpNewSub').value=''; rpPrefs(); rpChips(); rpBuildSections(); rpPreview(); }
      else if(b.id==='rpImg') rpToPng(rpHTML(rpModel(rpCur())),600,'Lesson_Report_'+($('rpName').value.trim()||'student')+'_'+$('rpDate').value);
      else if(b.id==='rpMAI') rpMonthAI(b);
      else if(b.id==='rpMAIUndo'){ $('rpMNote').value=RP_MAI_OLD||''; b.hidden=true; rpMonthRender(); }
      else if(b.id==='rpMImg'){ const m=rpMonthModel(); rpToPng(rpMonthHTML(m),820,'Teacher_Lesson_Record_'+m.month); }
      else if(b.id==='rpLast') rpLastTemplate();
      else if(b.id==='rpMTpl') $('rpMTplIn').click();
      else if(b.id==='rpMTplReset'){ mrMem=null; try{localStorage.removeItem(MR_KEY);}catch(e){} mrStatus(); mrLogoLoad(); toast('Using built-in form'); }
      else if(b.id==='rpMCopy') rpCopyText(rpMonthText());
      else if(b.id==='rpNew') rpReset();
      else if(b.dataset.rp){ const a=rpAll(), r=a.find(x=>x.id===b.dataset.id); if(!r) return;
        if(b.dataset.rp==='open'){ rpLoad(r); window.scrollTo({top:0,behavior:'smooth'}); }
        else if(b.dataset.rp==='tpl') rpTemplate(r);
        else if(b.dataset.rp==='copy') rpCopyText(rpTxtR(r));
        else if(b.dataset.rp==='del'&&confirm('Delete this report?')){ rpStore(a.filter(x=>x.id!==r.id)); rpTomb(r.id); if(REPF.id===r.id) REPF.id=null; rpList(); clSyncNow(true); } }
    });
  }
  rpPreview(); rpList();
}

